bool nativeSilverStopModelA0Trained() { return kTrained; }
const char *nativeSilverStopModelA0Id() { return kModelId; }
double nativeSilverStopModelA0DefaultThreshold() { return kDefaultThreshold; }

double nativeSilverStopModelA0Risk(const NativeSilverStopFeatures &x) {
    if (!kTrained) return 1.0;
    double raw = kBaseline;
    for (int t = 0; t < kTreeCount; ++t) {
        int n = kTreeRoots[t];
        while (!kNodes[n].leaf) {
            n = x[kNodes[n].feature] <= kNodes[n].threshold ? kNodes[n].left : kNodes[n].right;
        }
        raw += kNodes[n].value;
    }
    return 1.0 / (1.0 + std::exp(-raw));
}

